// dragon-volvelle: a loader / progress indicator that is Apian's lunar dragon volvelle (Astronomicum Caesareum,
// Ingolstadt 1540), its own paper disc turning on its pin over the printed mater.
//
// The control is a real <progress> inside the component. With a value, the disc has turned through that share of
// a full turn: the dragon's head (CAPVT) goes back through the zodiac the way the moon's node does, and at 100% it
// is home where it was printed. With no value (an indeterminate <progress>) the disc keeps going round, slowly.
// While it waits it can be handled: take the disc and turn it; let go and the work takes it back.
//
// At rest the <img> is the plate, pixel for pixel. Moving, a canvas over it draws the restored mater and the turned
// disc (assets/ring.webp, assets/disc.webp; geometry in assets/volvelle.json, cut offline by tools/).
//
//   import { dragonVolvelle } from './dragon-volvelle.js';
//   const v = dragonVolvelle(root);  v.value = .4;  v.value = null;  v.done();  v();  // destroy

const TAU = Math.PI * 2;
const calm = matchMedia('(prefers-reduced-motion: reduce)');
const live = new WeakMap();

const loadImage = (src) => new Promise((res, rej) => {
  const i = new Image();
  i.decoding = 'async';
  i.onload = () => (i.decode ? i.decode().catch(() => {}) : Promise.resolve()).then(() => res(i));
  i.onerror = rej;
  i.src = src;
});

function num(v, d) { const n = parseFloat(v); return Number.isFinite(n) ? n : d; }

export function dragonVolvelle(root, opts = {}) {
  if (live.has(root)) return live.get(root);
  const ds = root.dataset;
  const o = {
    turn: num(opts.turn ?? ds.turn, 40),               // seconds per turn while indeterminate
    speed: num(opts.speed ?? ds.speed, 100),           // most degrees a second the work turns it (by hand: any)
    touch: (opts.touch ?? ds.touch) !== false && (opts.touch ?? ds.touch) !== 'false',
    src: opts.src ?? ds.src,
    doneText: opts.doneText ?? ds.doneText ?? 'Done.',
  };
  const img = root.querySelector('.dv-img');
  const plateEl = root.querySelector('.dv-plate');
  const bar = root.querySelector('progress');
  const readout = root.querySelector('.dv-readout');
  if (!img || !plateEl) return Object.assign(() => {}, { value: null });

  const offs = [];
  const on = (t, e, f, p) => { t.addEventListener(e, f, p); offs.push(() => t.removeEventListener(e, f, p)); };
  const added = [];

  // ---- state -----------------------------------------------------------------------------------------------------
  let G = null;                 // geometry
  let ready = false;
  let theta = 0, omega = 0;     // the disc's turn (clockwise on screen = the nodes' regression) and its speed, rad, rad/s
  let base = 0;                 // whole turns already made (the target is base + value * TAU)
  let value = null;             // 0..1, or null while indeterminate
  let finished = false;
  let hand = null;              // {pid, a0, t0, last:[t, theta]}
  let raf = 0, lastT = 0, visible = true;
  let canvas, ctx, baseCv, discCv, scale = 1, dpr = 1, cssW = 0;

  root.classList.add('dv-on');
  if (o.touch) root.classList.add('dv-touch');

  // the live region: says start, every quarter, and done (the <progress> itself carries the exact value)
  const status = document.createElement('p');
  status.className = 'dv-status';
  status.setAttribute('role', 'status');
  root.appendChild(status); added.push(status);
  let spokenQuarter = -1;
  const say = (t) => { status.textContent = ''; requestAnimationFrame(() => { status.textContent = t; }); };

  // ---- reading the <progress> -----------------------------------------------------------------------------------
  function readBar() {
    if (!bar) return;
    const has = bar.hasAttribute('value');
    const max = num(bar.getAttribute('max'), 1) || 1;
    setValue(has ? Math.min(1, Math.max(0, num(bar.getAttribute('value'), 0) / max)) : null, false);
  }

  function setValue(v, writeBar = true) {
    const was = value;
    value = v == null ? null : Math.min(1, Math.max(0, v));
    if (writeBar && bar) {
      if (value == null) bar.removeAttribute('value');
      else bar.value = value * (num(bar.getAttribute('max'), 1) || 1);
    }
    if (value != null && (was == null || value < was)) {
      // from indeterminate, or a new job starting again: carry on forwards from wherever the disc has got to
      base = Math.ceil((theta - value * TAU) / TAU - 1e-6) * TAU;
    }
    if (value != null && value >= 1 && !finished) { finished = true; root.classList.add('dv-done'); }
    if (value != null && value < 1 && finished) { finished = false; root.classList.remove('dv-done'); }
    root.setAttribute('aria-busy', String(!(value != null && value >= 1)));
    root.classList.toggle('dv-indeterminate', value == null);
    if (readout) readout.textContent = value == null ? (readout.dataset.busy || '') : `${Math.round(value * 100)}%`;
    const q = value == null ? -1 : Math.floor(value * 4 + 1e-9);
    if (value != null && q !== spokenQuarter) {
      if (value >= 1) say(o.doneText);
      else if (q > spokenQuarter && q > 0) say(`${q * 25}%`);
      spokenQuarter = q;
    }
    if (value == null) spokenQuarter = -1;
    root.dispatchEvent(new CustomEvent('dragon-volvelle:change', { detail: { value } }));
    if (value != null && value >= 1 && was !== value) root.dispatchEvent(new CustomEvent('dragon-volvelle:done'));
    wake();
  }

  const mo = bar ? new MutationObserver(readBar) : null;
  if (mo) mo.observe(bar, { attributes: true, attributeFilter: ['value', 'max'] });

  // ---- drawing --------------------------------------------------------------------------------------------------
  function layout() {
    const w = plateEl.clientWidth;
    if (!w || !G) return;
    const d = Math.min(2, devicePixelRatio || 1);
    if (w === cssW && d === dpr && baseCv) return;
    cssW = w; dpr = d;
    scale = (w * dpr) / G.plate.w;
    const W = Math.round(G.plate.w * scale), H = Math.round(G.plate.h * scale);
    canvas.width = W; canvas.height = H;
    // cached base: the plate, with the restored mater laid over the ring the disc can uncover
    baseCv = document.createElement('canvas');
    baseCv.width = W; baseCv.height = H;
    const b = baseCv.getContext('2d');
    b.imageSmoothingQuality = 'high';
    b.drawImage(img, 0, 0, W, H);
    const sq = G.square;
    b.drawImage(G.ringImg, sq.x * scale, sq.y * scale, sq.size * scale, sq.size * scale);
    // the disc, resampled once to this size so each frame's turn is a 1:1 resample
    const s = Math.ceil(sq.size * scale);
    discCv = document.createElement('canvas');
    discCv.width = s; discCv.height = s;
    const dc = discCv.getContext('2d');
    dc.imageSmoothingQuality = 'high';
    dc.drawImage(G.discImg, 0, 0, s, s);
    draw();
  }

  function atRest() {
    const r = ((theta % TAU) + TAU) % TAU;
    return Math.min(r, TAU - r) < 1e-4 && Math.abs(omega) < 1e-4 && !hand && (value == null ? calm.matches : true);
  }

  function draw() {
    if (!ready || !baseCv) return;
    const rest = atRest();
    root.classList.toggle('dv-moving', !rest);
    if (rest) return;                       // the <img> is the plate
    ctx.setTransform(1, 0, 0, 1, 0, 0);
    ctx.drawImage(baseCv, 0, 0);
    const sq = G.square, px = G.pin[0] * scale, py = G.pin[1] * scale;
    ctx.translate(px, py);
    ctx.rotate(theta);
    ctx.imageSmoothingQuality = 'high';
    ctx.drawImage(discCv, sq.x * scale - px, sq.y * scale - py, sq.size * scale, sq.size * scale);
  }

  // ---- motion ---------------------------------------------------------------------------------------------------
  const target = () => base + (value ?? 0) * TAU;

  function step(dt) {
    if (hand) return;
    const vmax = (o.speed * Math.PI) / 180;
    if (calm.matches) {                     // reduced motion: put it where it would come to rest
      omega = 0;
      if (value != null) theta = target();
      return;
    }
    if (value == null) {
      // the work goes round: friction brings any flick back to a slow, steady turn
      const w0 = TAU / Math.max(4, o.turn);
      omega += (w0 - omega) * (1 - Math.exp(-dt / 1.4));
      theta += omega * dt;
    } else {
      // a critically damped spring to the value; the work never hurries it past vmax
      const wn = 3.2;
      const err = theta - target();
      const acc = -wn * wn * err - 2 * wn * omega;
      omega += acc * dt;
      if (Math.abs(omega) > vmax && Math.abs(err) > .02) omega = Math.sign(omega) * Math.max(vmax, Math.abs(omega) * Math.exp(-dt * 3));
      theta += omega * dt;
      if (Math.abs(theta - target()) < 2e-4 && Math.abs(omega) < 2e-3) { theta = target(); omega = 0; }
    }
  }

  function settled() {
    if (hand) return false;
    if (value == null) return calm.matches;
    return theta === target() && omega === 0;
  }

  function frame(t) {
    raf = 0;
    const dt = Math.min(.05, lastT ? (t - lastT) / 1000 : 1 / 60);
    lastT = t;
    for (let k = 0, n = Math.max(1, Math.round(dt * 240)); k < n; k++) step(dt / n);
    if (settled() && Math.abs(theta) > TAU) {          // keep the numbers small: drop whole turns
      const k = Math.floor(theta / TAU) * TAU;
      theta -= k; base -= k;
    }
    draw();
    if (visible && !document.hidden && !settled()) raf = requestAnimationFrame(frame);
    else lastT = 0;
  }

  function wake() {
    if (!ready || raf || !visible || document.hidden) return;
    lastT = 0;
    raf = requestAnimationFrame(frame);
  }

  // ---- the hand -------------------------------------------------------------------------------------------------
  function local(e) {
    const r = plateEl.getBoundingClientRect();
    const k = G.plate.w / r.width;
    return [(e.clientX - r.left) * k - G.pin[0], (e.clientY - r.top) * k - G.pin[1]];
  }
  function onDisc(e) {
    const [x, y] = local(e);
    const r = Math.hypot(x, y);
    if (r > G.r_max) return false;
    if (r <= G.r_disc + 2) return true;
    // beyond the disc only the tabs are paper: within a few degrees of where each tab points now
    const a = Math.atan2(y, x);
    return Object.values(G.tabs).some((t) => {
      let d = a - ((t.angle * Math.PI) / 180 + theta);
      d = Math.atan2(Math.sin(d), Math.cos(d));
      return Math.abs(d) < .065 && r < t.r_tip + 4;
    });
  }
  function down(e) {
    if (!ready || hand || (e.pointerType === 'mouse' && e.button !== 0) || !onDisc(e)) return;
    const [x, y] = local(e);
    hand = { pid: e.pointerId, a: Math.atan2(y, x), th: theta, hist: [[performance.now(), theta]] };
    omega = 0;
    plateEl.setPointerCapture?.(e.pointerId);
    root.classList.add('dv-grabbing');
    wake(); draw();
    e.preventDefault();
  }
  function move(e) {
    if (!hand) {
      if (ready && e.pointerType === 'mouse') plateEl.style.cursor = onDisc(e) ? 'grab' : '';
      return;
    }
    if (e.pointerId !== hand.pid) return;
    const [x, y] = local(e);
    let d = Math.atan2(y, x) - hand.a;
    d = Math.atan2(Math.sin(d), Math.cos(d));
    hand.a += d;
    theta += d;
    const now = performance.now();
    hand.hist.push([now, theta]);
    while (hand.hist.length > 2 && now - hand.hist[0][0] > 90) hand.hist.shift();
    draw();
  }
  function up(e) {
    if (!hand || e.pointerId !== hand.pid) return;
    const h = hand.hist, a = h[0], b = h[h.length - 1];
    const dt = (b[0] - a[0]) / 1000;
    omega = dt > .01 ? Math.max(-6, Math.min(6, (b[1] - a[1]) / dt)) : 0;
    hand = null;
    root.classList.remove('dv-grabbing');
    if (value != null) {
      // the work's own position is the nearest whole turn to where the hand left it
      base = Math.round((theta - value * TAU) / TAU) * TAU;
    }
    if (calm.matches) omega = 0;
    root.dispatchEvent(new CustomEvent('dragon-volvelle:turned', { detail: { angle: theta } }));
    wake();
  }
  // keyboard: the plate is focusable while it can be handled; arrows turn it a little
  function key(e) {
    if (!ready) return;
    const k = { ArrowLeft: -1, ArrowUp: -1, ArrowRight: 1, ArrowDown: 1 }[e.key];
    if (!k) return;
    e.preventDefault();
    omega += k * (calm.matches ? 0 : 1.2);
    if (calm.matches) theta += k * .2;
    wake(); draw();
  }

  // ---- start ----------------------------------------------------------------------------------------------------
  const jsonURL = o.src || new URL('volvelle.json', img.currentSrc || img.src).href;
  let alive = true;
  (async () => {
    try {
      const g = await (await fetch(jsonURL)).json();
      const dir = new URL('.', jsonURL).href;
      const [ringImg, discImg] = await Promise.all([loadImage(dir + 'ring.webp'), loadImage(dir + 'disc.webp')]);
      if (!img.complete) await new Promise((r) => img.addEventListener('load', r, { once: true }));
      if (!alive) return;
      G = Object.assign(g, { ringImg, discImg });
      canvas = document.createElement('canvas');
      canvas.className = 'dv-canvas';
      canvas.setAttribute('aria-hidden', 'true');
      plateEl.appendChild(canvas); added.push(canvas);
      ctx = canvas.getContext('2d');
      ready = true;
      layout();
      const ro = new ResizeObserver(() => layout());
      ro.observe(plateEl); offs.push(() => ro.disconnect());
      const io = new IntersectionObserver((es) => { visible = es[0].isIntersecting; if (visible) wake(); });
      io.observe(root); offs.push(() => io.disconnect());
      on(document, 'visibilitychange', () => wake());
      on(calm, 'change', () => wake());
      if (o.touch) {
        plateEl.tabIndex = plateEl.tabIndex >= 0 ? plateEl.tabIndex : 0;
        if (!plateEl.hasAttribute('aria-label')) plateEl.setAttribute('aria-label', 'Turn the disc by hand');
        on(plateEl, 'pointerdown', down);
        on(plateEl, 'pointermove', move);
        on(plateEl, 'pointerup', up);
        on(plateEl, 'pointercancel', up);
        on(plateEl, 'keydown', key);
      }
      root.classList.add('dv-ready');
      wake();
    } catch (err) {
      console.warn('dragon-volvelle: the plate will stay still', err);
    }
  })();
  readBar();
  if (!bar) setValue(opts.value ?? null, false);

  function destroy() {
    alive = false;
    cancelAnimationFrame(raf);
    mo?.disconnect();
    offs.forEach((f) => f());
    added.forEach((n) => n.remove());
    root.classList.remove('dv-on', 'dv-touch', 'dv-moving', 'dv-ready', 'dv-done', 'dv-grabbing', 'dv-indeterminate');
    root.removeAttribute('aria-busy');
    plateEl.style.cursor = '';
    live.delete(root);
  }
  Object.defineProperties(destroy, {
    value: { get: () => value, set: (v) => setValue(v) },
    angle: { get: () => theta },
  });
  destroy.done = () => setValue(1);
  destroy.hold = (h) => { if (h) cancelAnimationFrame(raf), (raf = 0), (visible = false); else (visible = true), wake(); };
  destroy.advance = (s) => { for (let k = 0; k < Math.round(s * 240); k++) step(1 / 240); draw(); };
  live.set(root, destroy);
  return destroy;
}

const start = () => document.querySelectorAll('[data-dragon-volvelle]').forEach((el) => dragonVolvelle(el));
if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start, { once: true });
else start();

/*
 *  VOLVELLE-BUTTON // the button part of dragon-volvelle.
 *
 *  A <button> with Peter Apian's lunar dragon volvelle (Astronomicum Caesareum, Ingolstadt 1540) in it: the paper
 *  disc and the ring of the printed mater it turns on, cut round from the plate's own pixels (assets/face.webp,
 *  ring.webp, disc.webp). Press it and a thumb takes CAPVT's tab: the disc turns a few degrees, and is held there
 *  while the button is down (a finger takes it as the button is pressed, since a touch may still turn into a scroll
 *  until it lifts). Let go and the button is busy: the disc turns on slowly while the work is done,
 *  following its progress (a whole job is one turn, home again at 100%), never faster than 36 degrees a second.
 *  The moment the work is done the button says so, and the disc comes to rest on the next sign of the zodiac:
 *  quick work sets it a sign or two on, long work brings it home, where it was printed.
 *
 *    <button type="button" class="vb" data-volvelle-button
 *            data-working="Uploading" data-done="Uploaded">Upload</button>
 *
 *  dragon-volvelle.js, unchanged, draws the disc: its canvas turns the disc's own pixels, rigid, about the centre
 *  printed on it, over the restored mater. This file gives it a button (states, words, aria, a polite status line,
 *  the press) and the pace: it says where the disc is, frame by frame.
 */
import { dragonVolvelle } from './dragon-volvelle.js';

const calm = typeof matchMedia === 'function' ? matchMedia('(prefers-reduced-motion: reduce)') : { matches: false };
const clamp = (v) => Math.min(1, Math.max(0, +v || 0));
const FACE = new URL('./assets/face.webp', import.meta.url).href;
const SS = 2;               // the canvas is drawn at twice the screen's pixels (see dense())
const SIGN = 30;            // deg: one sign of the zodiac. The disc comes to rest on one when the work is done
const TAKE = 5;             // deg: a press turns the disc this far (a thumb on CAPVT's tab), and holds it there
const TOUCH = 90;           // ms: a finger's press shows on the face after this long, in case it is starting a scroll
const HOLD = 28;            // rad/s: the disc follows the pace on a stiff, critically damped spring (about 0.15 s)
const ACC = 40, DEC = 50;   // deg/s2: the most the pace ever changes, speeding up and slowing down
const SET = 28;             // deg/s: carrying the disc on to its sign, once the work is over (or its own pace, if more)
const LAG = 0.8;            // s: the disc follows the work's progress about this far behind it
const STOP = 0.35;          // s: a job given up brakes to a stop where it is, in this time
const STEP = 1 / 240;       // s: the pace is worked out in steps this long

export function volvelleButton(btn, opts = {}) {
    if (btn.volvelleButton) return btn.volvelleButton;
    const ds = btn.dataset;
    const pick = (k, d) => opts[k] ?? ds[k] ?? d;
    const reset = +pick('reset', 2600);                 // ms showing the done word; 0 = stay done until reset()
    const auto = String(pick('auto', true)) !== 'false';
    const turn = Math.max(6, +pick('turn', 24) || 24);   // seconds a turn while there is no value yet
    const WAIT = 360 / turn;                            // deg/s while it waits: 15
    const MAX = Math.max(WAIT, +pick('speed', 36) || 36);  // deg/s: the most the work ever turns it
    const off = [], added = [];
    const on = (t, ev, fn, o) => { t.addEventListener(ev, fn, o); off.push(() => t.removeEventListener(ev, fn, o)); };
    let timer = 0, dead = false;

    /* ---- build: the roundel first, then the label stack ---- */
    const orig = Array.from(btn.childNodes);            // destroy() puts these back, in this order
    let face = btn.querySelector(':scope > img.vb-face');   // written in the HTML, the roundel shows without JS too
    if (!face) {
        face = document.createElement('img');
        face.className = 'vb-face'; face.alt = ''; face.width = face.height = 384; face.decoding = 'async';
        face.src = pick('face', FACE);
    }
    face.classList.add('dv-img');                       // the engine's plate: at home this <img> IS the roundel
    const disc = document.createElement('span'); disc.className = 'vb-disc';
    disc.setAttribute('aria-hidden', 'true');           // a button's children are presentational: the status line speaks
    const plate = document.createElement('span'); plate.className = 'dv-plate';
    const bar = document.createElement('progress'); bar.max = 1; bar.value = 0;    // value 0: home, still
    plate.appendChild(face); disc.append(plate, bar);
    btn.prepend(disc); added.push(disc);

    // the label: the button's own word, plus the working and done words, stacked in one grid cell. The cell is as
    // wide as the widest of them, so the pill is the same size in every state and nothing beside it reflows. Written
    // in the markup (span.vb-label, see the README), the pill has that width before the script runs; otherwise it is
    // built here from the button's text and data-working / data-done.
    let label = btn.querySelector(':scope > .vb-label');
    const ownLabel = !label;
    const was = [];                                     // an adopted label's words as written, for destroy()
    const say = {};
    let wrap = null;                                    // a written label with no stack of words: its text, wrapped
    if (label) {
        if (!label.querySelector(':scope > .vb-say')) {
            wrap = document.createElement('span'); wrap.className = 'vb-say vb-on';
            wrap.append(...label.childNodes); label.appendChild(wrap);
        }
        for (const s of label.querySelectorAll(':scope > .vb-say')) {
            if (s !== wrap) was.push([s, s.className, s.getAttribute('aria-hidden')]);
            const k = s.dataset.say || 'idle';
            if (!say[k]) say[k] = s;
        }
        if (!say.idle) say.idle = label.querySelector(':scope > .vb-say');
    } else {
        label = document.createElement('span'); label.className = 'vb-label';
        const idle = document.createElement('span'); idle.className = 'vb-say vb-on';
        for (const n of Array.from(btn.childNodes)) if (n !== disc) idle.appendChild(n);
        label.appendChild(idle); btn.appendChild(label);
        say.idle = idle;
    }
    const text = (say.idle.textContent || '').replace(/\s+/g, ' ').trim();
    const extra = [];                                   // words the script added to a written label
    for (const k of ['working', 'done']) {
        const t = opts[k] ?? (say[k] ? '' : ds[k] || '');
        if (!t) continue;
        if (say[k]) { if (opts[k] != null) { was.push([say[k], null, null, say[k].textContent]); say[k].textContent = t; } continue; }
        const s = document.createElement('span'); s.className = 'vb-say'; s.textContent = t;
        s.dataset.say = k;
        s.setAttribute('aria-hidden', 'true');          // only the word on show is in the button's name
        label.appendChild(s); say[k] = s;
        if (!ownLabel) extra.push(s);
    }
    const word = (k) => (say[k] ? say[k].textContent.replace(/\s+/g, ' ').trim() : text);
    const words = { working: word('working'), done: word('done') };
    let said = null;                                    // the word on show

    // the polite status line after the button (or the element named by data-status)
    let status = opts.status || (ds.status && document.getElementById(ds.status));
    const mine = !status;
    let roled = false;
    if (mine) {
        status = document.createElement('span'); status.className = 'vb-status'; status.setAttribute('role', 'status');
        added.push(status);
    } else if (!status.hasAttribute('role') && !status.hasAttribute('aria-live')) {
        status.setAttribute('role', 'status'); roled = true;   // the author's element speaks only as a live region
    }
    // after the button. A button made in script has no place for it yet: it goes in once there is one
    // (on focus, a press, or the first word said), and again if the button was moved into the page without it.
    const pin = () => {
        if (mine && btn.parentNode && !(status.parentNode && status.isConnected === btn.isConnected)) btn.after(status);
    };
    pin();

    /* ---- the volvelle: dragon-volvelle.js on the roundel, look-only (no drag-to-turn in a button) ---- */
    // speed: the engine's own spring is stepped to where the pace puts the disc (see feed), so its speed cap must
    // not hold it back there. Its own loop never moves the disc: the button holds it, and draws each frame itself.
    const loader = dragonVolvelle(disc, { touch: false, turn, speed: 3600, doneText: '' });
    // the engine adds its own live region; inside a button nothing would read it (and a <p> may not sit in one),
    // so it is taken out. The status line after the button speaks instead.
    const engineSays = disc.querySelector(':scope > .dv-status');
    if (engineSays) engineSays.remove();

    // the engine draws its canvas at most 2x. The plate is laid out larger by --vb-k and scaled back down
    // (volvelle-button.css), so the canvas is drawn at twice the screen's own pixels on any screen, and the turned
    // disc is as sharp as the resting <img>. The engine itself is unchanged.
    let dpr = 0, mq = null;
    function dense() {
        const d = devicePixelRatio || 1;
        if (d !== dpr) { dpr = d; disc.style.setProperty('--vb-k', String(SS * d / Math.min(2, d))); }
        if (mq) mq.removeEventListener('change', dense);
        mq = matchMedia(`(resolution: ${d}dppx)`);
        mq.addEventListener('change', dense);
    }
    dense();
