.dv-small .dv-hint { display: none; }

@media (forced-colors: active) {
  .dv-canvas { display: none !important; }
  .dv-moving .dv-img { visibility: visible; }
}

/* volvelle-button: the button part of dragon-volvelle. Everything is prefixed .vb-.
