    --vb-h: 56px; --vb-disc: 48px; --vb-pr: 24px;
    --vb-d: max(40px, var(--vb-disc));                       /* the roundel, never under 40px */
    --vb-hh: max(calc(var(--vb-d) + 8px), var(--vb-h));      /* the button, never under the roundel and its margin */
    --vb-face: var(--vb-paper, var(--paper, #f3f0e8));       /* the button's face */
